SELECT CASE WHEN accounts.balance >= 76000 THEN 'high' WHEN accounts.balance >= 10000 THEN 'mid' ELSE 'low' END AS balance_bucket, accounts.account_type, COUNT(transactions.amount) AS amount_count, AVG(transactions.amount) AS avg_amount FROM transactions FULL OUTER JOIN accounts ON transactions.account_id = accounts.id GROUP BY CASE WHEN accounts.balance >= 76000 THEN 'high' WHEN accounts.balance >= 10000 THEN 'mid' ELSE 'low' END, accounts.account_type
